#!/usr/bin/env python3# -*- coding: utf-8 -*-"""Created on Tue Jul 23 13:51:43 2024@author: ttaczak"""import numpy as npimport refrom scipy import interpolatefrom skimage import measurefrom matplotlib.path import Path as PTHdef get_equilibrium_data(eqdsk_path, verbose, wall_file, psi_min = 0.00001, num_contours = 30):    '''    Extracts the psin mesh from the equilibrium file (self.eqdsk).    Parameters    ----------    psi_min : FLOAT, optional        Minimum cutoff for psi for calculating the LCFS. The default is 0.00001.    Returns    -------    None.    '''    with open(eqdsk_path, 'r') as file:        lines = file.readlines()                        # Initialize variables    jm = 0                      # no. of grid points in radial direction    km = 0                      # no. of grid points in vertial direction    r = []                      # radial   coordinates of grid points   [m]    z = []                      # vertical coordinates of grid points   [m]    psib = 0.0                  # psi at plasma boundary           [Wb/rad]    psi = []                    # flux per radian at grid points   [Wb/rad]        btf = 0.0                   # toroidal magnetic field               [T]    rtf = 0.0                   # major radius at which btf is specified[m]    psi_rz = np.zeros((1))      # 2D equilibrium mesh        # Compile regex patterns    jm_pattern = re.compile(r'jm\s*=\s*(\d+)\s*;')    km_pattern = re.compile(r'km\s*=\s*(\d+)\s*;')    psib_pattern = re.compile(r'psib\s*=\s*([-+]?[0-9]*\.?[0-9]+(?:[eE][-+]?[0-9]+)?)')    btf_pattern = re.compile(r'btf\s*=\s*([-+]?[0-9]*\.?[0-9]+(?:[eE][-+]?[0-9]+)?)')    rtf_pattern = re.compile(r'rtf\s*=\s*([-+]?[0-9]*\.?[0-9]+(?:[eE][-+]?[0-9]+)?)')        # Read the first section    for line in lines:        if jm_pattern.search(line):            jm = int(jm_pattern.search(line).group(1))        elif km_pattern.search(line):            km = int(km_pattern.search(line).group(1))        elif psib_pattern.search(line):            psib = float(psib_pattern.search(line).group(1))        elif btf_pattern.search(line):            btf = float(btf_pattern.search(line).group(1))        elif rtf_pattern.search(line):            rtf = float(rtf_pattern.search(line).group(1))        # Read the r, z, and psi data    r_data_start = False    z_data_start = False    psi_data_start = False        for line in lines:        if line.strip().startswith('r('):            r_data_start = True            continue        if line.strip().startswith('z('):            z_data_start = True            r_data_start = False            continue        if line.strip().startswith('((psi('):            psi_data_start = True            z_data_start = False            continue            if r_data_start:            r.extend([float(val) for val in line.split()])        elif z_data_start:            z.extend([float(val) for val in line.split()])        elif psi_data_start:            psi.extend([float(val) for val in line.split()])                # extract wall data if it exists    if wall_file is not None:        wall_data = np.loadtxt(wall_file)/1000    else:        wall_data = None        # Convert lists to numpy arrays for convenience    r = np.array(r)    z = np.array(z)    # Create a meshgrid for r and z    R, Z = np.meshgrid(r, z)        psi = np.array(psi)    # Define a 2D profile for psi    psi = np.reshape(psi, (r.shape[0], r.shape[0]))            min_psi = np.min(psi)    max_psi = np.max(psi)    psin = (max_psi - psi) / (max_psi)    psi_rectspline = interpolate.RectBivariateSpline(R[0,:],Z[:,0], psin)        min_dist_contours = find_LCFS(psin,R,Z,num_contours)    # min_dist_contours_rescaled = rescale_contours(R,Z,psi,min_dist_contours)        LCFS = min_dist_contours[-1]            if verbose:        print(f'jm: {jm}')        print(f'km: {km}')        print(f'psib: {psib}')        print(f'btf: {btf}')        print(f'rtf: {rtf}')        print(f'r (m): {r}')        print(f'z (m): {z}')        print(f'r shape: {r.shape}')        print(f'z shape: {z.shape}')        print(f'psi shape: {psi.shape}')        return R, Z, psi_rectspline, psin, LCFS, wall_datadef find_LCFS(psin, R, Z, num_contours, plot = False):    '''    Limits the equilibrium to only the N'th contours around the maximum psi vlaue    '''    contour_values = np.linspace(0.0, 1.0, num = num_contours)        # Find the indices of the max value    i_psin_min, j_psin_min = np.unravel_index(np.argmin(psin), psin.shape)        # Get the corresponding (x, y) coordinates    R_psin_min = R[i_psin_min, j_psin_min]    Z_psin_min = Z[i_psin_min, j_psin_min]        center = np.atleast_2d([R_psin_min,Z_psin_min])        min_dist_contours = []    # Set the value at which you want to find contours    for contour_value in contour_values:            # Find contours at the given value        contours = measure.find_contours(psin, contour_value)                # Plot all found contours        for i, contour in enumerate(contours):                                # Switch image coordinates to logical R,Z coordinates (from Z, R to R, Z)            contour = np.array(contour)[...,[1, 0]]                                contour[:,0] = contour[:,0] / psin.shape[0] * (np.max(R) - np.min(R)) + np.min(R)            contour[:,1] = contour[:,1] / psin.shape[1] * (np.max(Z) - np.min(Z)) + np.min(Z)                        if points_in_polygon(center, contour)[0]:                min_dist_contours.append(contour)                        return min_dist_contours# def rescale_contours(R,Z,psi,min_dist_contours):    #     for contour in min_dist_contours:#         contour[:,0] = contour[:,0]/psi.shape[1] * (np.max(Z) - np.min(Z)) + np.min(Z)#         contour[:,1] = contour[:,1]/psi.shape[0] * (np.max(R) - np.min(R)) + np.min(R)        #     return min_dist_contoursdef points_in_polygon(points, polygon_coords):    """    Determine if multiple points are inside a polygon.    """    # Convert polygon to Path object    polygon_path = PTH(polygon_coords)        if not isinstance(points, np.ndarray):        # Convert points to a NumPy array for efficient checking        points_np = np.array(points)    else:        points_np = points        # Use Path's contains_points method to check all points at once    return polygon_path.contains_points(points_np)    def get_max_psi(R, Z, psi):    i, j = np.unravel_index(np.argmax(psi), psi.shape)    max_psi_indices = (i,j)    max_psi_location = np.array([R[i,j], Z[i,j]])    return max_psi_indices, max_psi_location    